/**
 * ATELO — curated finish & product catalogue.
 *
 * A compact, in-app dataset (300 products) used by the colour-analysis
 * swipe and finish browser. Weighted heavily toward paint colours with accurate
 * hex values from real ranges (Farrow & Ball, Benjamin Moore, Sherwin-Williams,
 * Little Greene, Dulux Heritage), plus stone, wood, metal, tile, cladding,
 * lighting and fixture finishes.
 *
 * A larger superset lives in supabase/catalog.sql for server-side querying.
 * Generated data — hand-curated hexes. Do not add duplicate ids.
 */

export type CatalogProduct = {
  id: string;            // stable kebab slug, e.g. "fb-hague-blue"
  category:
    | "paint"
    | "stone"
    | "wood"
    | "metal"
    | "tile"
    | "cladding"
    | "lighting"
    | "fixture";
  brand: string;
  name: string;
  hex: string;           // accurate 6-digit hex like "#1F2A2E"
  finish?: string;       // e.g. "Estate Emulsion", "Honed", "Brushed"
  description?: string;  // one short line
  tags?: string[];       // hue family + temperature/character, e.g. ["green","muted"]
};

